import json,struct,zipfile
from pathlib import Path
root=Path(__file__).resolve().parent
data=(root/'CraneCamera_3p2m.glb').read_bytes()
assert data[:4]==b'glTF' and struct.unpack_from('<I',data,8)[0]==len(data)
count=struct.unpack_from('<I',data,12)[0];doc=json.loads(data[20:20+count])
assert len(doc['meshes'])==1 and not doc.get('cameras') and not doc.get('skins')
assert all('uri' not in b for b in doc['buffers'])
assert (root/'CraneCamera_3p2m.fbx').read_bytes().startswith(b'Kaydara FBX Binary')
info=json.loads((root/'asset_info.json').read_text());assert abs(info['height_m']-3.2)<.001
(root/'README.txt').write_text('STYLIZED TRIPOD CRANE CAMERA\n\nComplete single static mesh assembly: camera, angled jib boom, pivot, operator handle, counterweights and three-legged tripod.\n\nHeight: 3.2 meters. Origin: ground center.\nFormats: GLB with embedded textures, FBX with textures, editable Blender source.\nSeparate texture PNG files are included for manual material setup. Normal map uses the glTF/OpenGL convention.\n\nGenerated by Hyper3D Rodin from a synthesized reference combining the user-provided crane structure and static-camera styling. The reference render is included. Final model scaled and exported with Blender.\nGeneration ID: 58c524cc-e61f-4ecb-8ffc-52395124b9bd\n\nStatic prop, not rigged or animated. Existing Unreal level assets have not been replaced.\n')
files=['CraneCamera_3p2m.glb','CraneCamera_3p2m.fbx','CraneCamera_3p2m.blend','preview.png','preview_back.png','crane_reference.png','asset_info.json','README.txt']
with zipfile.ZipFile(root/'CraneCamera_3p2m.zip','w',zipfile.ZIP_DEFLATED) as z:
 for filename in files:z.write(root/filename,filename)
 for file in (root/'textures').glob('*.png'):z.write(file,file.relative_to(root))
print(json.dumps({'validated':True,'dimensions_m':info['dimensions_m'],'zip_mb':round((root/'CraneCamera_3p2m.zip').stat().st_size/1024**2,1)}))
